use bee_shared::miner::SessionProof;
use bee_shared::miner::SessionSubmit;
use bee_shared::verifier::ParamsOfVerifySession;

use crate::bindings::exports::docs::bee_engine::verifier_interface::Guest as VerifierInterface;
use crate::error::LibError;
use crate::error::LibErrorCode;
use crate::verifier::validate_leaves;
use crate::verifier::validate_proof;
use crate::verifier::ParamsOfValidateLeaves;
use crate::verifier::ParamsOfValidateProof;

#[allow(warnings)]
mod bindings;

mod error;
mod verifier;

struct VerifierGuest {}

impl VerifierInterface for VerifierGuest {
    fn verify(req: Vec<u8>) -> Vec<u8> {
        // Decode params from binary data
        let params = match ParamsOfVerifySession::try_from(req) {
            Ok(value) => value,
            Err(e) => return LibError::new(LibErrorCode::DeserializeRequest, Some(e)).into(),
        };

        // Validate easy merkle proof and leaves
        let easy_valid = match VerifierGuest::verify_proof_and_leaves(
            &params.seed,
            params.easy_complexity,
            (params.easy_interval_start, params.easy_interval_end),
            params.easy_submit_params,
            params.easy_proof_params,
        ) {
            Ok(is_valid) => is_valid,
            Err(e) => return e.into(),
        };

        // Validate hard merkle proof and leaves
        let hard_first_valid = match VerifierGuest::verify_proof_and_leaves(
            &params.seed,
            params.hard_complexity,
            (0, 1),
            params.hard_submit_params.clone(),
            params.hard_first_proof_params.clone(),
        ) {
            Ok(is_valid) => is_valid,
            Err(e) => return e.into(),
        };

        let hard_range_valid = match VerifierGuest::verify_proof_and_leaves(
            &params.seed,
            params.hard_complexity,
            (params.hard_interval_start, params.hard_interval_end),
            params.hard_submit_params.clone(),
            params.hard_range_proof_params,
        ) {
            Ok(is_valid) => is_valid,
            Err(e) => return e.into(),
        };

        let hard_last_valid = match VerifierGuest::verify_proof_and_leaves(
            &params.seed,
            params.hard_complexity,
            (params.hard_submit_params.leaves_count - 1, params.hard_submit_params.leaves_count),
            params.hard_submit_params,
            params.hard_last_proof_params.clone(),
        ) {
            Ok(is_valid) => is_valid,
            Err(e) => return e.into(),
        };

        // First and last proofs are needed to calculate time in blocks
        // when hard computations have being performed.
        let hard_computation_blocks = {
            let Some(first_leaf) = params.hard_first_proof_params.leaves_data.first() else {
                return LibError::new(LibErrorCode::GetFirstHardLeaf, None).into();
            };
            let Some(last_leaf) = params.hard_last_proof_params.leaves_data.last() else {
                return LibError::new(LibErrorCode::GetLastHardLeaf, None).into();
            };

            ((last_leaf.timestamp - first_leaf.timestamp) / 330) as u32
        };

        // Generate result.
        //  - 1st byte: 1 - success, 0 - error
        //  - 2nd byte: 1 - proofs valid, 0 - 1 or all proofs are invalid
        //  - 3-6 bytes: 4 bytes in low-endian - number of blocks of hard computations
        let mut result = vec![1];
        result.push((easy_valid && hard_first_valid && hard_range_valid && hard_last_valid) as u8);
        result.extend_from_slice(hard_computation_blocks.to_le_bytes().as_slice());
        result
    }
}

impl VerifierGuest {
    fn verify_proof_and_leaves(
        seed: impl AsRef<str>,
        complexity: u32,
        interval: (u64, u64),
        submit_params: SessionSubmit,
        proof_params: SessionProof,
    ) -> Result<bool, LibError> {
        // Validate proof
        let valid_proof = validate_proof(ParamsOfValidateProof {
            root: submit_params.root,
            proof: proof_params.proof,
            leaves_count: submit_params.leaves_count as usize,
            leaves_chunk: proof_params.leaves_tree,
            leaves_indices: (interval.0 as usize..interval.1 as usize).collect::<Vec<_>>(),
        })?;

        // Validate leaves
        let valid_leaves = validate_leaves(ParamsOfValidateLeaves {
            seed: seed.as_ref().to_string(),
            complexity,
            leaves: proof_params.leaves_data,
        });

        Ok(valid_proof && valid_leaves)
    }
}

bindings::export!(VerifierGuest with_types_in bindings);

#[cfg(test)]
mod tests {

    use bee_shared::miner::leaf::ComputedLeaf;
    use bee_shared::miner::leaf::Leaf;
    use bee_shared::verifier::ParamsOfVerifySession;

    use crate::bindings::exports::docs::bee_engine::verifier_interface::Guest;
    use crate::VerifierGuest;

    trait HexDecodeExt {
        fn decode_hex(&self) -> Vec<u8>;
    }

    impl HexDecodeExt for str {
        fn decode_hex(&self) -> Vec<u8> {
            hex::decode(self).unwrap()
        }
    }

    fn wasm_bytes_arg() -> String {
        "".to_string()
    }

    #[test]
    fn test_hash() {
        let computed_leaf = ComputedLeaf {
            hash: "0011ffde34458bb9369bd0336a3f437263ffe3edf4a0bdcb5e89ae9a44736275".decode_hex(),
            nonce: 2249,
            index: 10,
            seed: "0x0000".to_string(),
            x: 0,
            y: 0,
            timestamp: 1765010819137,
            complexity: 10,
        };

        let leaf = Leaf {
            index: computed_leaf.index,
            nonce: computed_leaf.nonce,
            seed: computed_leaf.seed.clone(),
            x: computed_leaf.x,
            y: computed_leaf.y,
            timestamp: computed_leaf.timestamp,
            complexity: computed_leaf.complexity,
        };

        assert_eq!(computed_leaf.hash, leaf.compute().hash);
    }

    #[test]
    fn test_deserialize() {
        let params =
            ParamsOfVerifySession::try_from(hex::decode(wasm_bytes_arg()).unwrap()).unwrap();
        assert_eq!(
            params.seed,
            "0x00000000000000000000000000000000000000000000000000000000b21c5aef"
        );

        assert_eq!(params.easy_complexity, 10);
        assert_eq!(
            hex::encode(params.easy_submit_params.root),
            "a5324ee2020affbe4f9d03f7466d269723ee975947d0a000734258d62a173d85"
        );
        assert_eq!(params.easy_submit_params.leaves_count, 1920);

        assert_eq!(params.hard_complexity, 11);
        assert_eq!(
            hex::encode(params.hard_submit_params.root),
            "c707b69425c1bee63ee8f5e70fb957743843892a8c342918673f97941f87e586"
        );
        assert_eq!(params.hard_submit_params.leaves_count, 1056);
    }

    #[test]
    fn test_verify() {
        let result = VerifierGuest::verify(hex::decode(wasm_bytes_arg()).unwrap());
        assert_eq!(result, vec![1, 1, 15, 0, 0, 0])
    }
}
